/**
 * Small byte-array helpers shared by the SHA-1 / HMAC / PBKDF2 modules.
 *
 * Everything here works on plain `Uint8Array`s; no Node Buffer, no node:crypto.
 */

/** Pre-computed '00'..'ff' table so toHex() is a single lookup per byte. */
const HEX = (() => {
  const table = new Array(256);
  for (let i = 0; i < 256; i += 1) {
    table[i] = i.toString(16).padStart(2, '0');
  }
  return table;
})();

/**
 * Render bytes as a lowercase hex string (like Python's `bytes.hex()`).
 * @param {Uint8Array} u8
 * @returns {string}
 */
export function toHex(u8) {
  let out = '';
  for (let i = 0; i < u8.length; i += 1) {
    out += HEX[u8[i]];
  }
  return out;
}

/**
 * XOR `src` into `dst` in place. Both arrays must have the same length
 * (PBKDF2 only ever folds equal-sized HMAC digests together).
 * @param {Uint8Array} dst mutated in place
 * @param {Uint8Array} src
 * @returns {Uint8Array} the same `dst` instance, for chaining
 */
export function xorInto(dst, src) {
  for (let i = 0; i < dst.length; i += 1) {
    dst[i] ^= src[i];
  }
  return dst;
}

/**
 * Concatenate a list of byte arrays into one fresh Uint8Array.
 * @param {Uint8Array[]} chunks
 * @returns {Uint8Array}
 */
export function concatBytes(chunks) {
  let total = 0;
  for (let i = 0; i < chunks.length; i += 1) {
    total += chunks[i].length;
  }
  const out = new Uint8Array(total);
  let offset = 0;
  for (let i = 0; i < chunks.length; i += 1) {
    out.set(chunks[i], offset);
    offset += chunks[i].length;
  }
  return out;
}

/**
 * Encode a number as 4 big-endian bytes (PBKDF2's `struct.pack('!L', i)`).
 * Values are taken modulo 2**32, matching unsigned 32-bit packing.
 * @param {number} n
 * @returns {Uint8Array} length 4
 */
export function uint32be(n) {
  const v = n >>> 0;
  return new Uint8Array([(v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff]);
}

/**
 * Compare two byte arrays for equality.
 * @param {Uint8Array} a
 * @param {Uint8Array} b
 * @returns {boolean}
 */
export function bytesEqual(a, b) {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

/**
 * Python text-codec emulation.
 *
 * Two things Python does that JavaScript does not:
 *
 *  1. `bytes.decode('utf-8', 'surrogateescape')` — undecodable bytes survive the
 *     round trip as lone surrogates U+DC80..U+DCFF instead of being replaced by
 *     U+FFFD. CPython uses this to decode `sys.argv`, so a raw 0xFF on the
 *     command line becomes the character U+DCFF.
 *  2. `str.encode('utf-8')` (strict) — which then *refuses* those lone
 *     surrogates with a UnicodeEncodeError. That is exactly the runtime error
 *     path the reference program takes for invalid argv bytes.
 */

import { readFileSync } from 'node:fs';
import process from 'node:process';
import { PyUnicodeEncodeError } from './pyerror.mjs';

/** Flush the pending UTF-16 code units this often to keep `apply` args small. */
const FLUSH_AT = 4096;

/**
 * Length of the valid UTF-8 sequence starting at `i`, or 0 if the bytes at `i`
 * do not begin a well-formed sequence.
 *
 * Rejects exactly what CPython's strict UTF-8 decoder rejects: continuation
 * bytes used as a lead, the C0/C1 overlong two-byte forms, E0 80..9F and
 * F0 80..8F overlongs, ED A0..BF (UTF-16 surrogates encoded as UTF-8),
 * F4 90..BF and F5..FF (beyond U+10FFFF), and truncated sequences.
 *
 * @param {Uint8Array} b
 * @param {number} i
 * @returns {number} 1, 2, 3, 4 or 0
 */
function sequenceLength(b, i) {
  const b0 = b[i];
  if (b0 < 0x80) return 1;

  // 0x80..0xC1 can never lead: continuation bytes and the overlong 2-byte forms.
  if (b0 < 0xc2) return 0;

  if (b0 <= 0xdf) {
    const b1 = b[i + 1];
    return b1 >= 0x80 && b1 <= 0xbf ? 2 : 0;
  }

  if (b0 <= 0xef) {
    // Lower bound on the second byte kills the E0 overlongs; the ED cap keeps
    // U+D800..U+DFFF out (Python will not decode CESU-8 style surrogates).
    const lo = b0 === 0xe0 ? 0xa0 : 0x80;
    const hi = b0 === 0xed ? 0x9f : 0xbf;
    const b1 = b[i + 1];
    const b2 = b[i + 2];
    if (b1 === undefined || b1 < lo || b1 > hi) return 0;
    return b2 >= 0x80 && b2 <= 0xbf ? 3 : 0;
  }

  if (b0 <= 0xf4) {
    // F0 90..BF (no overlongs) .. F4 80..8F (stop at U+10FFFF).
    const lo = b0 === 0xf0 ? 0x90 : 0x80;
    const hi = b0 === 0xf4 ? 0x8f : 0xbf;
    const b1 = b[i + 1];
    const b2 = b[i + 2];
    const b3 = b[i + 3];
    if (b1 === undefined || b1 < lo || b1 > hi) return 0;
    if (!(b2 >= 0x80 && b2 <= 0xbf)) return 0;
    return b3 >= 0x80 && b3 <= 0xbf ? 4 : 0;
  }

  // 0xF5..0xFF: no code point is that large.
  return 0;
}

/**
 * Decode bytes the way Python's `bytes.decode('utf-8', 'surrogateescape')` does.
 *
 * Valid sequences decode normally (astral code points become a JS surrogate
 * *pair*). Every byte the strict decoder rejects becomes U+DC00+byte on its
 * own and decoding resumes at the very next byte. That per-byte resume is
 * equivalent to CPython's "escape the whole rejected span" behaviour, because
 * every byte inside such a span is a continuation byte that could not start a
 * sequence either — verified against the reference binary for truncated,
 * overlong, surrogate and out-of-range inputs.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function utf8SurrogateEscapeDecode(bytes) {
  let out = '';
  const units = [];
  let i = 0;

  while (i < bytes.length) {
    const n = sequenceLength(bytes, i);

    if (n === 0) {
      units.push(0xdc00 + bytes[i]);
      i += 1;
    } else if (n === 1) {
      units.push(bytes[i]);
      i += 1;
    } else if (n === 2) {
      units.push(((bytes[i] & 0x1f) << 6) | (bytes[i + 1] & 0x3f));
      i += 2;
    } else if (n === 3) {
      units.push(((bytes[i] & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f));
      i += 3;
    } else {
      const cp =
        ((bytes[i] & 0x07) << 18) |
        ((bytes[i + 1] & 0x3f) << 12) |
        ((bytes[i + 2] & 0x3f) << 6) |
        (bytes[i + 3] & 0x3f);
      const v = cp - 0x10000;
      units.push(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
      i += 4;
    }

    if (units.length >= FLUSH_AT) {
      out += String.fromCharCode.apply(null, units);
      units.length = 0;
    }
  }

  if (units.length > 0) out += String.fromCharCode.apply(null, units);
  return out;
}

/**
 * Find the first lone surrogate in a string, using Python code-point indexing.
 *
 * `for..of` iterates code points, so a well-formed surrogate *pair* yields one
 * astral code point (and counts as position 1, exactly like Python), while an
 * unpaired U+D800..U+DFFF yields itself.
 *
 * @param {string} str
 * @returns {{index: number, codePoint: number}|null}
 */
export function findSurrogateEscape(str) {
  let index = 0;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xd800 && cp <= 0xdfff) return { index, codePoint: cp };
    index += 1;
  }
  return null;
}

/**
 * Encode a string with Python's strict UTF-8 codec.
 *
 * @param {string} str
 * @returns {Uint8Array}
 * @throws {PyUnicodeEncodeError} if the string holds a lone surrogate
 */
export function encodeUtf8Strict(str) {
  const bad = findSurrogateEscape(str);
  if (bad !== null) throw new PyUnicodeEncodeError(bad.codePoint, bad.index);

  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Uint8Array.from(out);
}

/**
 * Split a NUL-separated /proc/self/cmdline buffer into byte slices, dropping
 * the single empty chunk produced by the trailing NUL (an argument that really
 * is the empty string must survive).
 *
 * @param {Uint8Array} buf
 * @returns {Uint8Array[]}
 */
function splitNul(buf) {
  const parts = [];
  let start = 0;
  for (let i = 0; i < buf.length; i += 1) {
    if (buf[i] === 0) {
      parts.push(buf.subarray(start, i));
      start = i + 1;
    }
  }
  if (start < buf.length) parts.push(buf.subarray(start, buf.length));
  return parts;
}

/**
 * The user arguments (everything after the script path) as Python would see
 * them: raw kernel bytes decoded with UTF-8 + surrogateescape.
 *
 * Node has already lossily decoded `process.argv`, so we re-read the original
 * bytes from /proc/self/cmdline when that is available and its argument count
 * lines up. Any mismatch or I/O failure falls back to `process.argv.slice(2)`;
 * this function never throws.
 *
 * @returns {string[]}
 */
export function rawArgv() {
  const fallback = process.argv.slice(2);
  try {
    const want = process.argv.length - 2;
    if (want <= 0) return fallback;

    const buf = readFileSync('/proc/self/cmdline');
    const parts = splitNul(new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength));
    if (parts.length < want) return fallback;

    return parts.slice(parts.length - want).map(utf8SurrogateEscapeDecode);
  } catch {
    return fallback;
  }
}

