export class PyUnicodeEncodeError extends Error {
  constructor(codePoint, position) {
    super('enc');
    this.codePoint = codePoint;
    this.position = position;
  }
}

import { utf8SurrogateEscapeDecode, findSurrogateEscape, encodeUtf8Strict } from './pycodec.mjs';
import { toHex, xorInto, concatBytes, uint32be, bytesEqual } from './bytes.mjs';

const samples = [
  '',
  'abc',
  'café',
  '密码パス',
  '\u{1f600}\u{1f511}',
  '߿ࠀ￿',
  '\u{10000}',
  '\u{10ffff}',
];

const enc = new TextEncoder();
for (const s of samples) {
  const e = encodeUtf8Strict(s);
  if (toHex(e) !== toHex(enc.encode(s))) console.log('ENC FAIL', JSON.stringify(s));
  const d = utf8SurrogateEscapeDecode(e);
  if (d !== s) console.log('ROUNDTRIP FAIL', JSON.stringify(s), JSON.stringify(d));
}

// exhaustive: every code point encodes and decodes back identically
for (let cp = 0; cp <= 0x10ffff; cp += 1) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  const s = String.fromCodePoint(cp);
  const e = encodeUtf8Strict(s);
  if (toHex(e) !== toHex(enc.encode(s))) {
    console.log('CP ENC FAIL', cp.toString(16));
    break;
  }
  if (utf8SurrogateEscapeDecode(e) !== s) {
    console.log('CP DEC FAIL', cp.toString(16));
    break;
  }
}

// every 1..3 byte sequence: decoder must agree with a strict reference decoder
function refDecode(bytes) {
  // TextDecoder with fatal:true, byte-window search, used only as a cross-check
  const dec = new TextDecoder('utf-8', { fatal: true });
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    let ok = false;
    for (let n = 1; n <= 4 && i + n <= bytes.length; n += 1) {
      try {
        const piece = dec.decode(bytes.subarray(i, i + n));
        out += piece;
        i += n;
        ok = true;
        break;
      } catch {
        /* keep widening */
      }
    }
    if (!ok) {
      out += String.fromCharCode(0xdc00 + bytes[i]);
      i += 1;
    }
  }
  return out;
}

let mismatches = 0;
for (let a = 0; a < 256 && mismatches < 5; a += 1) {
  for (let b = 0; b < 256 && mismatches < 5; b += 1) {
    for (let c = 0; c < 256 && mismatches < 5; c += 1) {
      const u = new Uint8Array([a, b, c]);
      const mine = utf8SurrogateEscapeDecode(u);
      const ref = refDecode(u);
      if (mine !== ref) {
        console.log('DEC MISMATCH', toHex(u), JSON.stringify(mine), JSON.stringify(ref));
        mismatches += 1;
      }
    }
  }
}

console.log('findSurrogateEscape:', JSON.stringify(findSurrogateEscape('\u{1f600}\udcff')));
console.log('findSurrogateEscape:', JSON.stringify(findSurrogateEscape('A\u{1f600}\udcffB')));
console.log('findSurrogateEscape:', findSurrogateEscape('abc'));
console.log('uint32be:', toHex(uint32be(1)), toHex(uint32be(0xffffffff)), toHex(uint32be(0x01020304)));
console.log('concat:', toHex(concatBytes([new Uint8Array([1, 2]), new Uint8Array(0), new Uint8Array([255])])));
console.log('concat empty:', toHex(concatBytes([])));
console.log('xor:', toHex(xorInto(new Uint8Array([0xf0, 0x0f]), new Uint8Array([0xff, 0xff]))));
console.log('eq:', bytesEqual(new Uint8Array([1, 2]), new Uint8Array([1, 2])), bytesEqual(new Uint8Array([1]), new Uint8Array([1, 2])));
try {
  encodeUtf8Strict('a\udcff');
  console.log('NO THROW');
} catch (e) {
  console.log('threw', e.constructor.name, e.codePoint.toString(16), e.position);
}
console.log('t1 done, mismatches =', mismatches);

import { rawArgv, findSurrogateEscape } from './pycodec.mjs';

function pyRepr(s) {
  // minimal repr, enough for the ASCII + surrogate-escape test inputs
  let out = "'";
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xd800 && cp <= 0xdfff) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (ch === "'") {
      out += "\\'";
    } else {
      out += ch;
    }
  }
  return out + "'";
}

const args = rawArgv();
console.log(JSON.stringify(args.length));
console.log(args.map(pyRepr).join(' | '));
console.log(JSON.stringify(findSurrogateEscape(args[0] ?? '')));

import { writeFileSync } from 'node:fs';
import { utf8SurrogateEscapeDecode, findSurrogateEscape } from './pycodec.mjs';

// Bias the random pool toward the interesting UTF-8 ranges.
const POOL = [];
for (let b = 0x41; b <= 0x5a; b += 1) POOL.push(b); // ASCII
for (let b = 0x80; b <= 0xff; b += 1) POOL.push(b, b); // leads + continuations, weighted
for (const b of [0xc0, 0xc1, 0xc2, 0xe0, 0xed, 0xf0, 0xf4, 0xf5, 0xa0, 0x9f, 0x8f, 0x90, 0xbf]) {
  for (let k = 0; k < 6; k += 1) POOL.push(b);
}

let seed = 0x2f6e2b1;
function rnd(n) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed % n;
}

const cases = [];
const lines = ['#!/bin/bash'];
for (let t = 0; t < 400; t += 1) {
  const len = 1 + rnd(7);
  const bytes = [0x5a]; // 'Z' so the value never starts with '-'
  for (let i = 0; i < len; i += 1) bytes.push(POOL[rnd(POOL.length)]);
  bytes.push(0xff); // guarantee at least one escape

  const u8 = Uint8Array.from(bytes);
  const decoded = utf8SurrogateEscapeDecode(u8);
  const found = findSurrogateEscape(decoded);
  cases.push({ hex: Buffer.from(u8).toString('hex'), expected: found === null ? -1 : found.index });

  const quoted = bytes.map((b) => '\\x' + b.toString(16).padStart(2, '0')).join('');
  lines.push(`./test2_executable --a $'${quoted}' --b s --c 1 2>&1 | tail -2 | head -1`);
}

writeFileSync('/tmp/sc/probe.sh', lines.join('\n') + '\n');
writeFileSync('/tmp/sc/cases.json', JSON.stringify(cases));
console.log('generated', cases.length);

import { readFileSync } from 'node:fs';

const cases = JSON.parse(readFileSync('/tmp/sc/cases.json', 'utf8'));
const lines = readFileSync('/tmp/sc/probe.out', 'utf8').split('\n');

let bad = 0;
for (let i = 0; i < cases.length; i += 1) {
  const line = lines[i];
  const m = /in position (\d+)(?:-(\d+))?:/.exec(line);
  const got = m ? Number(m[1]) : -1;
  if (got !== cases[i].expected) {
    bad += 1;
    if (bad <= 8) console.log('MISMATCH', cases[i].hex, 'expected', cases[i].expected, 'got', got, '|', line);
  }
}
console.log('total', cases.length, 'mismatches', bad);

// how often does the reference use the plural/range form?
const ranges = lines.filter((l) => /position \d+-\d+:/.test(l)).length;
console.log('range-form messages:', ranges, 'single-form:', lines.filter((l) => /position \d+:/.test(l)).length);

