 * "can't encode characters in position 1-3" (inclusive, no character repr).
 *
 * @param {string} str
 * @returns {{index: number, codePoint: number, endIndex: number}|null}
 */
export function findSurrogateEscape(str) {
  let index = 0;
  let start = -1;
  let codePoint = 0;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    const isSurrogate = cp >= 0xd800 && cp <= 0xdfff;
    if (isSurrogate && start < 0) {
      start = index;
      codePoint = cp;
    } else if (!isSurrogate && start >= 0) {
      return { index: start, codePoint, endIndex: index - 1 };
    }
    index += 1;
  }
  return start < 0 ? null : { index: start, codePoint, endIndex: index - 1 };
}

