  if (!lines[i].includes(mine)) {
    bad += 1;
    if (bad <= 8) console.log('RANGE MISMATCH', cases[i].hex, mine, '|', lines[i]);
  }
}
console.log('range check: total', cases.length, 'mismatches', bad);
